/**
 * Dynamic Agent Manager — Loads, caches, and manages agent runtimes from DB config.
 * Handles both design-time agent overrides and runtime-created dynamic agents.
 * Generated by Mindbricks Genesis Engine for the AgentHub service.
 */
const { getToolsForAgent, callRemoteTool } = require("./tool-catalog-manager");

// Runtime cache: Map<agentName, { runtime, config, loadedAt }>
const runtimeCache = new Map();
const CACHE_TTL_MS = 60 * 1000; // 1 minute cache

/**
 * Create a tool handler that proxies calls to a remote service.
 */
function createRemoteToolHandler(tool) {
  return async function (args, context) {
    const headers = {};
    if (context?.session?.token) {
      headers["Authorization"] = `Bearer ${context.session.token}`;
    }
    return await callRemoteTool(tool.toolName, args, headers);
  };
}

/**
 * Build a tool registry from selectedTools list.
 * Each tool becomes a callable function that proxies to the source service.
 */
function buildToolRegistryFromCatalog(selectedTools) {
  const tools = getToolsForAgent(selectedTools);
  const registry = {};

  for (const tool of tools) {
    registry[tool.toolName] = {
      name: tool.toolName,
      description: tool.description,
      parameters: tool.parameters,
      handler: createRemoteToolHandler(tool),
    };
  }

  return registry;
}

/**
 * Load a design-time agent with runtime overrides merged.
 * The compiled runtime is the base; DB overrides are applied on top.
 */
async function loadDesignAgentConfig(agentName, compiledAgents) {
  const compiled = compiledAgents?.[agentName];
  if (!compiled) return null;

  // Fetch override from DB
  let override = null;
  try {
    const { getSys_agentOverrideByQuery } = require("dbLayer");
    override = await getSys_agentOverrideByQuery({ agentName });
  } catch (_) {}

  if (!override) {
    // No override — return compiled config as-is
    return {
      type: "design",
      name: agentName,
      config: compiled,
      override: null,
      selectedTools: null, // Use compiled tools
    };
  }

  // Check if disabled
  if (override.enabled === false) {
    return { type: "design", name: agentName, disabled: true };
  }

  // Merge override onto compiled config
  return {
    type: "design",
    name: agentName,
    config: compiled,
    override: {
      provider: override.provider,
      model: override.model,
      systemPrompt: override.systemPrompt,
      temperature: override.temperature,
      maxTokens: override.maxTokens,
      responseFormat: override.responseFormat,
      guardrails: override.guardrails,
    },
    selectedTools: override.selectedTools, // Override tools from catalog
  };
}

/**
 * Resolve an agent by name — checks design-time agents first, then dynamic.
 * Returns the agent config or null if not found.
 */
async function resolveAgent(agentName, compiledAgents) {
  // Check cache first
  const cached = runtimeCache.get(agentName);
  if (cached && Date.now() - cached.loadedAt < CACHE_TTL_MS) {
    return cached.agentConfig;
  }

  // Try design-time agent
  const designConfig = await loadDesignAgentConfig(agentName, compiledAgents);
  if (designConfig) {
    runtimeCache.set(agentName, {
      agentConfig: designConfig,
      loadedAt: Date.now(),
    });
    return designConfig;
  }

  return null;
}

/**
 * Invalidate the runtime cache for an agent (called when overrides or dynamic agents are updated).
 */
function invalidateAgentCache(agentName) {
  runtimeCache.delete(agentName);
  console.log(
    `[DynamicAgentManager] Cache invalidated for agent: ${agentName}`,
  );
}

/**
 * Invalidate all cached runtimes.
 */
function invalidateAllCaches() {
  runtimeCache.clear();
  console.log("[DynamicAgentManager] All agent caches invalidated");
}

/**
 * List all available agents (design-time + dynamic).
 */
async function listAvailableAgents(compiledAgentNames) {
  const agents = [];

  // Design-time agents
  for (const name of compiledAgentNames || []) {
    agents.push({ name, type: "design" });
  }

  return agents;
}

module.exports = {
  resolveAgent,
  buildToolRegistryFromCatalog,
  invalidateAgentCache,
  invalidateAllCaches,
  listAvailableAgents,
  loadDesignAgentConfig,
  runtimeCache,
};
